module TopModule (
    input  logic clk,
    input  logic areset,
    input  logic bump_left,
    input  logic bump_right,
    output logic walk_left,
    output logic walk_right
);

    typedef enum logic {
        S_LEFT  = 1'b0,
        S_RIGHT = 1'b1
    } state_t;

    state_t state, next_state;

    always_ff @(posedge clk, posedge areset) begin
        if (areset)
            state <= S_LEFT;
        else
            state <= next_state;
    end

    always_comb begin
        if (bump_left && bump_right)
            next_state = ~state;
        else if (bump_left)
            next_state = S_RIGHT;
        else if (bump_right)
            next_state = S_LEFT;
        else
            next_state = state;
    end

    assign walk_left  = (state == S_LEFT);
    assign walk_right = (state == S_RIGHT);

endmodule

